[data-slot="sidebar"] div:has(> [data-slot="input-control"] > input[type="search"]),[data-slot="sidebar"] div:has(> input[type="search"]){border-radius:9px !important;transition:background-color 0.18s ease,box-shadow 0.2s ease !important}
