[data-thread-item] button[aria-label="Unpin thread"] > svg:first-child path,[data-thread-item] svg[aria-label="Pinned"] path,[data-slot="sidebar"] button[title^="Unpin "] > svg:first-child path{fill:currentColor !important;stroke:currentColor !important}
